from datetime import datetime, timezone

from app.extensions import db


class Attachment(db.Model):

    __tablename__ = "attachments"

    id = db.Column(
        db.Integer,
        primary_key=True
    )

    report_id = db.Column(
        db.Integer,
        db.ForeignKey("reports.id"),
        nullable=False,
        index=True
    )

    # Original filename supplied by the user
    original_filename = db.Column(
        db.String(255),
        nullable=False
    )

    # Internal filename generated by the application
    stored_filename = db.Column(
        db.String(255),
        unique=True,
        nullable=False
    )

    # File metadata
    mime_type = db.Column(
        db.String(100),
        nullable=False
    )

    file_size = db.Column(
        db.Integer,
        nullable=False
    )

    storage_path = db.Column(
        db.String(500),
        nullable=False
    )

    # Moderation
    moderation_status = db.Column(
        db.String(20),
        nullable=False,
        default="pending"
    )

    is_public = db.Column(
        db.Boolean,
        nullable=False,
        default=False
    )

    uploaded_at = db.Column(
        db.DateTime(timezone=True),
        nullable=False,
        default=lambda: datetime.now(timezone.utc)
    )

    # Relationship
    report = db.relationship(
        "Report",
        backref=db.backref(
            "attachments",
            lazy="dynamic"
        )
    )

    def __repr__(self):
        return f"<Attachment {self.stored_filename}>"
